--
--  Por clase: si no está, avisa y sigue; si no tiene experiencia,
--  retira (borrado lógico) el texto corto de la siembra e inserta la
--  experiencia como primer bloque, conservando videos y enlaces; si ya
--  la tiene, la actualiza. Si el curso está publicado, deja aprobada
--  una versión nueva (077). Nunca detiene el arranque.
-- ============================================================

DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacoterapia del Asma y la EPOC$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacoterapia del Asma y la EPOC$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: farmacoterapia del asma y la EPOC en 2026
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El inhalador que se acaba antes de tiempo","texto":"Una paciente con asma retira seis inhaladores de salbutamol en un año y ningún corticoide inhalado. Llega a urgencias con una crisis. En la farmacia, ese patrón era visible meses antes. Reconocerlo a tiempo es una de las competencias que este curso desarrolla."},"objetivos":["Resumir el alcance del curso y sus guías de referencia.","Reconocer la carga del asma y la EPOC.","Identificar el rol del QF en la farmacoterapia respiratoria.","Aplicar el marco normativo colombiano."],"conceptos":[{"icono":"Wind","termino":"Asma","definicion":"Inflamación crónica variable de la vía aérea."},{"icono":"Activity","termino":"EPOC","definicion":"Obstrucción persistente asociada a exposición."},{"icono":"BookOpen","termino":"GINA y GOLD","definicion":"Guías internacionales vigentes para asma y EPOC."},{"icono":"Users","termino":"Rol del QF","definicion":"Dispensación informada, educación y seguimiento."}],"secciones":[{"titulo":"Por qué importa","parrafos":["El asma y la enfermedad pulmonar obstructiva crónica son las enfermedades respiratorias crónicas más frecuentes. La OMS estima cientos de millones de personas con asma y millones de muertes anuales por EPOC, que es una de las principales causas de muerte en el mundo.","Gran parte de los fracasos terapéuticos se explica por errores de técnica inhalatoria, baja adherencia y uso excesivo de broncodilatadores de rescate. Estos problemas son detectables desde la farmacia y son el centro del trabajo del químico farmacéutico."]},{"titulo":"Las guías del curso","parrafos":["El curso usa la Estrategia GINA 2026 para el asma y el Informe GOLD 2026 para la EPOC, complementados con las guías de práctica clínica del Ministerio de Salud, el inserto aprobado por el INVIMA, el Decreto 780 de 2016, la Resolución 1403 de 2007 y el Programa Nacional de Farmacovigilancia.","Las cinco unidades recorren fundamentos y diagnóstico, farmacología de broncodilatadores y controladores, tratamiento escalonado del asma, tratamiento de la EPOC y exacerbaciones, y dispositivos, adherencia, prevención y seguimiento. El anexo reúne fichas de medicamentos para consulta rápida."]},{"titulo":"El rol del químico farmacéutico","parrafos":["El QF participa en la dispensación informada, la educación sobre técnica y adherencia, la detección de problemas relacionados con medicamentos, la conciliación y el seguimiento farmacoterapéutico. También identifica señales de seguridad y las reporta al INVIMA.","El curso propone un enfoque práctico: cada clase conecta la evidencia con situaciones colombianas y termina con un caso aplicado. La meta no es memorizar dosis, sino tomar decisiones seguras y documentadas."]}],"errores":[{"error":"Dispensar sin revisar el patrón de uso.","correccion":"El historial de retiros es un indicador."},{"error":"Creer que el curso es solo teórico.","correccion":"Cada clase termina en un caso aplicado."},{"error":"Ignorar las guías nacionales.","correccion":"El inserto y la norma colombiana prevalecen."}],"comprueba":[{"pregunta":"¿Qué guías usa el curso?","respuesta":"GINA 2026 y GOLD 2026."},{"pregunta":"¿Cuál es el rol central del QF?","respuesta":"Dispensación informada, educación y seguimiento."},{"pregunta":"¿Qué indica el sobreuso de SABA?","respuesta":"Asma no controlada y mayor riesgo."}],"resumen":["El asma y la EPOC son enfermedades frecuentes y tratables.","La técnica y la adherencia explican gran parte del fracaso.","GINA 2026 y GOLD 2026 son las referencias del curso.","El QF detecta y previene problemas desde la farmacia."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"},{"cita":"Organización Mundial de la Salud. Asma: nota descriptiva. OMS; 2026.","url":"https://www.who.int/es/news-room/fact-sheets/detail/asthma"}],"imagenes":[{"ubicacion":"Introducción","descripcion":"Farmacéutico revisando el historial de inhaladores de un paciente.","alt":"Introducción a la farmacoterapia del asma y la EPOC"}],"keywords":["curso asma epoc","farmacoterapia respiratoria","gina 2026","gold 2026","rol químico farmacéutico"],"mapa":{"centro":"Curso asma y EPOC","ramas":[{"titulo":"Fundamentos","icono":"Search","nodos":["Definición","Diagnóstico","Diferencial"]},{"titulo":"Fármacos","icono":"Pill","nodos":["SABA","LABA","ICS","LAMA"]},{"titulo":"Tratamiento","icono":"Route","nodos":["Asma","EPOC","Exacerbaciones"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["Técnica","Adherencia","Vacunas"]}]},"proceso":{"titulo":"Cómo estudiar el curso","intro":"","pasos":[{"titulo":"Contextualizar","detalle":"Leer el caso y la meta de la clase.","icono":"Target","evidencia":"Meta."},{"titulo":"Comprender","detalle":"Estudiar mecanismos y criterios.","icono":"BookOpen","evidencia":"Notas."},{"titulo":"Aplicar","detalle":"Resolver el caso con la guía.","icono":"Workflow","evidencia":"Decisión."},{"titulo":"Verificar","detalle":"Responder las comprobaciones.","icono":"ClipboardCheck","evidencia":"Resultado."},{"titulo":"Transferir","detalle":"Llevarlo a la práctica diaria.","icono":"Repeat","evidencia":"Plan."}]},"caso":{"titulo":"Seis salbutamoles en un año","contexto":"Paciente con asma que retira seis inhaladores de salbutamol al año y ningún corticoide inhalado.","pregunta":"¿Qué significa este patrón?","opciones":[{"texto":"Que el asma está bien controlada.","correcta":false,"retro":"El sobreuso de rescate indica riesgo."},{"texto":"Que hay sobreuso de rescate y falta de tratamiento controlador.","correcta":true,"retro":"Es una señal de alarma detectable en farmacia."},{"texto":"Que necesita más salbutamol.","correcta":false,"retro":"Aumentar el rescate no controla la inflamación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: farmacoterapia del asma y la EPOC en 2026$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción al curso: farmacoterapia del asma y la EPOC en 2026$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Asma: definición, fenotipos y criterios diagnósticos según GINA 2026
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La tos que solo aparece de noche","texto":"Una mujer joven consulta por tos nocturna y sibilancias que empeoran con el polvo. Su espirometría mejora con salbutamol. El asma se confirma con síntomas variables y evidencia de limitación variable del flujo. Confirmar el diagnóstico antes de tratar cambia el pronóstico."},"objetivos":["Definir el asma y sus fenotipos.","Aplicar los criterios de variabilidad y reversibilidad.","Interpretar espirometría y biomarcadores.","Reconocer el valor de confirmar el diagnóstico."],"conceptos":[{"icono":"Wind","termino":"Asma","definicion":"Enfermedad heterogénea con inflamación crónica y limitación variable."},{"icono":"LineChart","termino":"Reversibilidad","definicion":"Aumento del FEV1 de 12 % y 200 mL o más."},{"icono":"Activity","termino":"PEF","definicion":"Flujo espiratorio máximo; ayuda a mostrar variabilidad."},{"icono":"TestTube","termino":"FeNO","definicion":"Biomarcador de inflamación tipo 2; apoya el diagnóstico."}],"secciones":[{"titulo":"Definición y clínica","parrafos":["El asma es una enfermedad heterogénea con inflamación crónica de la vía aérea. Se caracteriza por síntomas respiratorios que varían en el tiempo y en intensidad: sibilancias, disnea, opresión torácica y tos. Suelen empeorar de noche o con el ejercicio y se desencadenan con infecciones virales, alérgenos, humo, cambios de temperatura o perfumes.","La variabilidad es una pista central. Un patrón estacional, nocturno o relacionado con exposiciones apoya el diagnóstico, pero no lo confirma por sí solo. GINA 2026 exige dos elementos: historia compatible y evidencia de limitación variable del flujo aéreo."]},{"titulo":"Criterios diagnósticos","parrafos":["En adultos, la prueba broncodilatadora es positiva si el FEV1 o la FVC aumentan 12 % o más y 200 mL o más respecto al basal. Un aumento del PEF de 20 % o más también apoya. En niños se usa un aumento del FEV1 de 12 % o más del valor predicho. La variabilidad del PEF mayor de 10 % en dos semanas en adultos, o 13 % en niños, es otro criterio.","Los biomarcadores tipo 2, como el FeNO mayor de 50 ppb en adultos o los eosinófilos elevados en sangre, apoyan el diagnóstico, aunque valores bajos no lo descartan. GINA 2026 simplificó su algoritmo y advierte que los criterios previos llevaban a subdiagnóstico, sobre todo en hombres jóvenes."]},{"titulo":"Fenotipos y consecuencias","parrafos":["Los fenotipos alérgico, eosinofílico, no tipo 2 y asociado a obesidad orientan el tratamiento del asma grave. También ayudan a elegir biológicos cuando el paciente no responde al tratamiento inhalado optimizado.","Lo ideal es confirmar el diagnóstico antes de iniciar un controlador, porque después es más difícil demostrar la variabilidad. En la dispensación, el QF puede preguntar por el patrón de síntomas, el uso de rescate y los desencadenantes, y remitir si el diagnóstico no está claro."]}],"errores":[{"error":"Diagnosticar sin espirometría.","correccion":"La evidencia objetiva es necesaria."},{"error":"Tratar sin confirmar la variabilidad.","correccion":"Después es más difícil demostrarla."},{"error":"Confundir asma con EPOC por la edad.","correccion":"La historia y la variabilidad orientan."}],"comprueba":[{"pregunta":"¿Qué criterio de reversibilidad usa GINA en adultos?","respuesta":"FEV1 o FVC +12 % y +200 mL."},{"pregunta":"¿Qué biomarcador apoya el diagnóstico?","respuesta":"FeNO mayor de 50 ppb o eosinófilos elevados."},{"pregunta":"¿Qué exige GINA 2026?","respuesta":"Síntomas variables y limitación variable del flujo."}],"resumen":["El asma es heterogénea y variable.","La espirometría con prueba broncodilatadora es clave.","El FeNO y los eosinófilos apoyan el diagnóstico.","Confirmar antes de tratar mejora el manejo."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Ministerio de Salud y Protección Social. Guía de práctica clínica de asma (Guía n.º 01). Bogotá; 2013.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/INEC/IETS/GPC_Comp_Asma.pdf"}],"imagenes":[{"ubicacion":"Diagnóstico","descripcion":"Curva de espirometría con prueba broncodilatadora positiva.","alt":"Criterios diagnósticos de asma GINA 2026"}],"keywords":["asma diagnóstico","gina 2026 asma","reversibilidad fev1","feno","fenotipos asma"],"mapa":{"centro":"Diagnóstico de asma","ramas":[{"titulo":"Síntomas","icono":"Wind","nodos":["Sibilancias","Disnea","Tos","Opresión"]},{"titulo":"Variabilidad","icono":"LineChart","nodos":["Nocturno","Ejercicio","Estacional"]},{"titulo":"Pruebas","icono":"TestTube","nodos":["Espirometría","PEF","FeNO"]},{"titulo":"Fenotipos","icono":"Network","nodos":["Alérgico","Eosinofílico","No tipo 2","Obesidad"]}]},"proceso":{"titulo":"Ruta diagnóstica","intro":"","pasos":[{"titulo":"Historia","detalle":"Síntomas variables y desencadenantes.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Espirometría","detalle":"FEV1, FVC y prueba broncodilatadora.","icono":"LineChart","evidencia":"Informe."},{"titulo":"Variabilidad","detalle":"PEF o FeNO según el caso.","icono":"Activity","evidencia":"Registro."},{"titulo":"Diferencial","detalle":"Descartar EPOC y otras causas.","icono":"Search","evidencia":"Juicio."},{"titulo":"Confirmar","detalle":"Documentar antes de tratar.","icono":"FileCheck","evidencia":"Historia."}]},"caso":{"titulo":"Tos nocturna y polvo","contexto":"Mujer de 24 años en Cali con tos nocturna y sibilancias desde hace seis meses, que empeoran con el polvo. La espirometría sube de 2,40 a 2,75 L tras salbutamol.","pregunta":"¿Qué criterio se cumple?","opciones":[{"texto":"Ninguno; es solo rinitis.","correcta":false,"retro":"La reversibilidad es significativa."},{"texto":"Reversibilidad: +350 mL y +14,6 %.","correcta":true,"retro":"Cumple el criterio de GINA y apoya el asma."},{"texto":"Solo la variabilidad del PEF.","correcta":false,"retro":"La espirometría ya muestra reversibilidad."}]}}$j$::jsonb;
