  -- 03. EPOC: definición, factores de riesgo y diagnóstico espirométrico según GOLD 2026
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La disnea del exfumador","texto":"Un hombre de 62 años que fumó 30 paquetes-año consulta por disnea al caminar. Su espirometría muestra FEV1/FVC de 0,62. La EPOC se confirma con obstrucción persistente y exposición de riesgo. El diagnóstico temprano permite intervenir antes de la siguiente exacerbación."},"objetivos":["Definir la EPOC y sus factores de riesgo.","Aplicar el criterio espirométrico de GOLD.","Clasificar la gravedad y los grupos ABE.","Reconocer el papel del QF en el diagnóstico temprano."],"conceptos":[{"icono":"Activity","termino":"EPOC","definicion":"Obstrucción persistente por alteraciones de vía aérea o alvéolos."},{"icono":"LineChart","termino":"FEV1/FVC","definicion":"Menor de 0,70 posbroncodilatador confirma obstrucción."},{"icono":"Flame","termino":"Tabaco","definicion":"Principal factor de riesgo, sin ser el único."},{"icono":"Wind","termino":"Biomasa","definicion":"Humo de leña o carbón; relevante en zonas rurales."}],"secciones":[{"titulo":"Definición y factores de riesgo","parrafos":["GOLD define la EPOC como una condición pulmonar heterogénea con síntomas respiratorios crónicos y obstrucción persistente y a menudo progresiva del flujo aéreo, causada por alteraciones de la vía aérea o de los alvéolos. Se debe sospechar en personas con disnea, tos o expectoración crónica, infecciones respiratorias bajas a repetición o exposición a factores de riesgo.","Los factores de riesgo incluyen el tabaco, el humo de biomasa, el polvo y los químicos ocupacionales, el asma en la infancia y eventos tempranos como bajo peso al nacer. En Colombia, la contaminación del aire doméstico tiene un peso importante en zonas rurales donde todavía se cocina con leña. El déficit de alfa-1 antitripsina causa EPOC de inicio temprano."]},{"titulo":"Diagnóstico espirométrico","parrafos":["El diagnóstico exige espirometría con una relación FEV1/FVC posbroncodilatador menor de 0,70 en un contexto clínico compatible. GOLD 2026 lo califica como obligatorio. La espirometría prebroncodilatador sirve para descartar, pero el criterio definitivo es posbroncodilatador.","La gravedad de la obstrucción se clasifica por el FEV1 posbroncodilatador en GOLD 1 (80 % o más del predicho), GOLD 2 (50-79 %), GOLD 3 (30-49 %) y GOLD 4 (menos de 30 %). La evaluación inicial combina obstrucción, síntomas con mMRC o CAT y riesgo de exacerbaciones para asignar el grupo A, B o E."]},{"titulo":"Detección desde la farmacia","parrafos":["El QF puede sospechar EPOC en personas que retiran broncodilatadores de forma repetida, tienen tos crónica o usan nebulizaciones caseras sin diagnóstico claro. Preguntar por tabaquismo, humo de leña y exposición laboral ayuda a identificar candidatos a espirometría.","La derivación oportuna y la educación sobre cesación tabáquica y vacunación modifican la historia natural. El diagnóstico no termina en la espirometría: exige evaluar síntomas, exacerbaciones, comorbilidades y capacidad de usar dispositivos."]}],"errores":[{"error":"Diagnosticar sin espirometría.","correccion":"El criterio es objetivo."},{"error":"Usar solo el FEV1 para tratar.","correccion":"Síntomas y exacerbaciones definen el grupo."},{"error":"Ignorar la biomasa.","correccion":"Es un riesgo relevante en Colombia."}],"comprueba":[{"pregunta":"¿Qué confirma la EPOC?","respuesta":"FEV1/FVC menor de 0,70 posbroncodilatador."},{"pregunta":"¿Cómo se clasifica la gravedad?","respuesta":"GOLD 1 a 4 por FEV1."},{"pregunta":"¿Qué evalúa el grupo ABE?","respuesta":"Síntomas y exacerbaciones."}],"resumen":["La EPOC es heterogénea y prevenible.","El tabaco y la biomasa son riesgos clave.","La espirometría posbroncodilatador es obligatoria.","El grupo ABE guía el tratamiento inicial."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"},{"cita":"Ministerio de Salud y Protección Social, Colciencias. Guía de práctica clínica de EPOC (Guía n.º 28). Bogotá; 2014.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/INEC/IETS/GPC_Comp_EPOC.pdf"}],"imagenes":[{"ubicacion":"Diagnóstico","descripcion":"Espirometría con obstrucción persistente y clasificación GOLD.","alt":"Diagnóstico de EPOC según GOLD 2026"}],"keywords":["epoc diagnóstico","gold 2026 epoc","espirometría fev1/fvc","biomasa epoc","grupos abe"],"mapa":{"centro":"EPOC","ramas":[{"titulo":"Riesgo","icono":"Flame","nodos":["Tabaco","Biomasa","Ocupacional","Alfa-1"]},{"titulo":"Diagnóstico","icono":"LineChart","nodos":["Espirometría","FEV1/FVC","Posbroncodilatador"]},{"titulo":"Gravedad","icono":"Gauge","nodos":["GOLD 1","GOLD 2","GOLD 3","GOLD 4"]},{"titulo":"Evaluación","icono":"ClipboardList","nodos":["mMRC","CAT","Exacerbaciones"]}]},"proceso":{"titulo":"Ruta diagnóstica de EPOC","intro":"","pasos":[{"titulo":"Sospechar","detalle":"Síntomas y exposiciones.","icono":"Search","evidencia":"Entrevista."},{"titulo":"Espirometría","detalle":"FEV1/FVC posbroncodilatador.","icono":"LineChart","evidencia":"Informe."},{"titulo":"Clasificar","detalle":"GOLD 1-4 por FEV1.","icono":"Gauge","evidencia":"Estadio."},{"titulo":"Evaluar","detalle":"mMRC, CAT y exacerbaciones.","icono":"ClipboardList","evidencia":"Grupo."},{"titulo":"Intervenir","detalle":"Cesación, vacunas y tratamiento.","icono":"ShieldCheck","evidencia":"Plan."}]},"caso":{"titulo":"Don Álvaro en Tunja","contexto":"Hombre de 62 años, exfumador de 30 paquetes-año, expuesto a leña, con disnea al caminar (mMRC 2), CAT 18, sin exacerbaciones y FEV1/FVC de 0,62; FEV1 58 %.","pregunta":"¿Qué grupo y tratamiento inicial corresponden?","opciones":[{"texto":"Grupo A; solo SABA.","correcta":false,"retro":"Tiene síntomas; requiere mantenimiento."},{"texto":"Grupo B; LABA+LAMA.","correcta":true,"retro":"GOLD 2026 recomienda LABA+LAMA en grupo B."},{"texto":"Grupo E; triple terapia.","correcta":false,"retro":"No hay exacerbaciones."}]}}$j$::jsonb;
