  -- 04. Diagnóstico diferencial entre asma y EPOC y superposición de rasgos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Asma desde niño y tabaco","texto":"Un hombre de 55 años con asma desde la infancia y 20 paquetes-año de tabaquismo recibe solo un LAMA. La obstrucción es persistente, pero la historia y la reversibilidad sugieren asma. Sin corticoide inhalado, el riesgo de exacerbaciones aumenta."},"objetivos":["Comparar asma y EPOC.","Reconocer la superposición de rasgos.","Interpretar reversibilidad y biomarcadores.","Aplicar la consecuencia terapéutica."],"conceptos":[{"icono":"Wind","termino":"Asma","definicion":"Inicio temprano, atopia y variabilidad."},{"icono":"Activity","termino":"EPOC","definicion":"Inicio tardío, exposición y obstrucción persistente."},{"icono":"Network","termino":"Superposición","definicion":"Rasgos de ambas enfermedades en un paciente."},{"icono":"Pill","termino":"ICS","definicion":"Obligatorio si hay rasgos de asma."}],"secciones":[{"titulo":"Diferencias clínicas","parrafos":["El asma suele iniciar en la infancia o juventud, se asocia con atopia y sus síntomas varían mucho de un día a otro; la obstrucción es variable y puede normalizarse. La EPOC suele aparecer después de los 40 años en personas expuestas al tabaco o a la biomasa, con síntomas persistentes y progresivos y una obstrucción que no se normaliza.","La respuesta al broncodilatador no basta para separarlas: algunas personas con EPOC tienen reversibilidad y algunas con asma de larga evolución tienen obstrucción fija. Por eso se integran la historia, la espirometría, la variabilidad y los biomarcadores."]},{"titulo":"Superposición asma-EPOC","parrafos":["La superposición se reconoce cuando coexisten rasgos de ambas: inicio temprano o atopia junto con tabaquismo intenso y obstrucción persistente. El FeNO y los eosinófilos en sangre ayudan a caracterizar la inflamación, pero son complementos y no sustituyen la valoración clínica.","En estos pacientes el riesgo de exacerbaciones es alto. La decisión terapéutica debe individualizarse y documentarse, porque las guías de asma y de EPOC dan recomendaciones distintas para el mismo paciente."]},{"titulo":"Consecuencia terapéutica","parrafos":["En el asma, GINA indica que todo paciente debe recibir un tratamiento que contenga corticoide inhalado y desaconseja los broncodilatadores solos. En la EPOC, la base son los broncodilatadores de acción prolongada y el ICS se reserva para pacientes con exacerbaciones y eosinófilos elevados.","Si una persona tiene rasgos de ambas, el ICS no debe faltar. Retirarlo por considerarla EPOC puede descompensar el asma. El QF puede detectar esta situación al revisar la medicación y comunicarla al médico con argumentos claros."]}],"errores":[{"error":"Separar por la reversibilidad sola.","correccion":"No distingue de forma fiable."},{"error":"No buscar rasgos de asma.","correccion":"Cambian el tratamiento."},{"error":"Retirar el ICS al rotular EPOC.","correccion":"Puede descompensar el asma."}],"comprueba":[{"pregunta":"¿Qué distingue al asma?","respuesta":"Inicio temprano y variabilidad."},{"pregunta":"¿Qué distingue a la EPOC?","respuesta":"Exposición y obstrucción persistente."},{"pregunta":"¿Qué fármaco no debe faltar si hay asma?","respuesta":"El corticoide inhalado."}],"resumen":["Asma y EPOC comparten síntomas.","La reversibilidad aislada no las separa.","La superposición es frecuente.","Si hay asma, el ICS es obligatorio."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Diferencial","descripcion":"Comparación de historia, espirometría y tratamiento entre asma y EPOC.","alt":"Diagnóstico diferencial asma y EPOC"}],"keywords":["diferencial asma epoc","superposición asma epoc","aco","eosinófilos asma","ics asma"],"mapa":{"centro":"Asma vs EPOC","ramas":[{"titulo":"Historia","icono":"Users","nodos":["Edad","Atopia","Tabaco"]},{"titulo":"Función","icono":"LineChart","nodos":["Variable","Persistente","Reversibilidad"]},{"titulo":"Biomarcadores","icono":"TestTube","nodos":["Eosinófilos","FeNO","IgE"]},{"titulo":"Tratamiento","icono":"Pill","nodos":["ICS","LABA","LAMA"]}]},"proceso":{"titulo":"Cómo diferenciarlas","intro":"","pasos":[{"titulo":"Historia","detalle":"Edad de inicio, atopia y exposición.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Espirometría","detalle":"Variabilidad y obstrucción.","icono":"LineChart","evidencia":"Informe."},{"titulo":"Biomarcadores","detalle":"Eosinófilos y FeNO.","icono":"TestTube","evidencia":"Resultado."},{"titulo":"Integrar","detalle":"Rasgos de superposición.","icono":"Network","evidencia":"Juicio."},{"titulo":"Tratar","detalle":"Incluir ICS si hay asma.","icono":"Pill","evidencia":"Plan."}]},"caso":{"titulo":"Solo LAMA en un asmático","contexto":"Hombre de 55 años en Pereira, fumador de 20 paquetes-año, con asma desde niño, obstrucción persistente y reversibilidad de 15 %. Recibe solo LAMA.","pregunta":"¿Qué haría usted?","opciones":[{"texto":"Mantener solo LAMA.","correcta":false,"retro":"No es adecuado si hay rasgos de asma."},{"texto":"Comentar con el médico para incluir ICS.","correcta":true,"retro":"El ICS no debe faltar en el asma."},{"texto":"Suspender todo tratamiento inhalado.","correcta":false,"retro":"Empeoraría el control."}]}}$j$::jsonb;
