  -- 05. Contexto colombiano: guías nacionales, cobertura y servicio farmacéutico
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cuarenta pacientes sin corticoide","texto":"En una IPS de Montería, el QF cruza los códigos J45 y J44 con las dispensaciones y encuentra 40 pacientes con asma que solo retiran salbutamol. La gestión de datos y el conocimiento de la cobertura convierten esa lista en una intervención."},"objetivos":["Resumir el marco normativo colombiano.","Aplicar la codificación CIE-10 y la cobertura.","Reconocer las brechas del sistema.","Diseñar una intervención desde la farmacia."],"conceptos":[{"icono":"FileText","termino":"CIE-10","definicion":"J45 para asma y J44 para EPOC."},{"icono":"Landmark","termino":"PBS","definicion":"Plan de Beneficios en Salud con cargo a la UPC."},{"icono":"Gavel","termino":"Resolución 1403","definicion":"Modelo de gestión del servicio farmacéutico."},{"icono":"LineChart","termino":"Brechas","definicion":"Control subóptimo, acceso y falta de seguimiento."}],"secciones":[{"titulo":"Marco normativo","parrafos":["En Colombia, el diagnóstico se registra con la CIE-10: J45 para asma y J44 para EPOC. Es la base de las rutas de atención y de los programas de enfermedades crónicas de las EPS. El MinSalud publicó la guía de asma en 2013 y la de EPOC en 2014; no se encontró una actualización oficial, por lo que conviene contrastarlas con GINA 2026 y GOLD 2026.","El servicio farmacéutico se rige por el Decreto 780 de 2016 y la Resolución 1403 de 2007, que incluyen la dispensación informada, la atención farmacéutica y el seguimiento farmacoterapéutico. El Programa Nacional de Farmacovigilancia del INVIMA recibe los reportes de eventos adversos."]},{"titulo":"Cobertura y acceso","parrafos":["La financiación de medicamentos depende del Plan de Beneficios en Salud con cargo a la UPC. Para 2026 se publicó el listado de servicios y tecnologías financiados mediante la Resolución 2765 de 2025, vigente desde el 1 de enero de 2026. El QF debe verificar qué inhaladores y presentaciones están incluidos y cuáles requieren otro mecanismo.","Un artículo de mayo de 2025 señala que en el país persisten el control subóptimo del asma, el bajo uso de las guías, las brechas de acceso y la falta de educación y seguimiento. Estas brechas son oportunidades concretas para el servicio farmacéutico."]},{"titulo":"Intervención desde la farmacia","parrafos":["Con los códigos J45 y J44, el historial de dispensaciones y los registros de atención, el QF puede priorizar pacientes con sobreuso de SABA, sin ICS, con mala técnica o con exacerbaciones recientes. La intervención combina educación, remisión documentada y seguimiento telefónico.","Un programa de pacientes respiratorios bien diseñado mide indicadores simples: porcentaje con ICS, inhaladores de rescate por año, técnica correcta, vacunación y exacerbaciones. Presentar esos resultados al comité de farmacia sostiene la intervención en el tiempo."]}],"errores":[{"error":"No verificar la cobertura.","correccion":"El acceso condiciona la adherencia."},{"error":"No documentar la intervención.","correccion":"Sin registro no se sostiene."},{"error":"Ignorar las guías nacionales.","correccion":"Complementan las internacionales."}],"comprueba":[{"pregunta":"¿Qué códigos CIE-10 se usan?","respuesta":"J45 para asma y J44 para EPOC."},{"pregunta":"¿Qué norma rige el servicio farmacéutico?","respuesta":"Decreto 780 de 2016 y Resolución 1403 de 2007."},{"pregunta":"¿Qué resolución actualiza el PBS 2026?","respuesta":"Resolución 2765 de 2025."}],"resumen":["La CIE-10 estructura la atención.","El PBS define el acceso a inhaladores.","Persisten brechas de control y educación.","El QF puede intervenir con datos y seguimiento."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 2765 de 2025: listado de servicios y tecnologías financiados con la UPC. Bogotá; 2025.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Forms/DispForm.aspx?ID=7000"},{"cita":"Ministerio de la Protección Social. Resolución 1403 de 2007: Modelo de Gestión del Servicio Farmacéutico. Bogotá; 2007.","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minproteccion_1403_2007.htm"}],"imagenes":[{"ubicacion":"Contexto","descripcion":"Mapa de Colombia con brechas de acceso a inhaladores.","alt":"Contexto colombiano del asma y la EPOC"}],"keywords":["asma colombia","epoc colombia","pbs inhaladores","resolución 1403","seguimiento farmacéutico"],"mapa":{"centro":"Contexto colombiano","ramas":[{"titulo":"Normas","icono":"Gavel","nodos":["Decreto 780","Resolución 1403","INVIMA"]},{"titulo":"Cobertura","icono":"Landmark","nodos":["PBS","UPC","Resolución 2765"]},{"titulo":"Datos","icono":"Database","nodos":["CIE-10","Dispensación","Registros"]},{"titulo":"Brechas","icono":"AlertTriangle","nodos":["Acceso","Educación","Seguimiento"]}]},"proceso":{"titulo":"Intervención poblacional","intro":"","pasos":[{"titulo":"Identificar","detalle":"Códigos y dispensaciones.","icono":"Database","evidencia":"Listado."},{"titulo":"Priorizar","detalle":"Sobreuso y falta de ICS.","icono":"Filter","evidencia":"Cohorte."},{"titulo":"Contactar","detalle":"Educación y remisión.","icono":"Users","evidencia":"Registro."},{"titulo":"Medir","detalle":"Indicadores de proceso.","icono":"LineChart","evidencia":"Informe."},{"titulo":"Sostener","detalle":"Comité y seguimiento.","icono":"Repeat","evidencia":"Plan."}]},"caso":{"titulo":"Programa respiratorio en Montería","contexto":"Una IPS encuentra 40 pacientes con asma que solo retiran salbutamol.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Nada; no es su función.","correcta":false,"retro":"El seguimiento es parte del servicio farmacéutico."},{"texto":"Prioriza remisión, educación y revisión de cobertura.","correcta":true,"retro":"Convierte los datos en intervención."},{"texto":"Suspende el salbutamol a todos.","correcta":false,"retro":"No se suspende sin valoración médica."}]}}$j$::jsonb;
