  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El análisis que ordena el caso","texto":"Don Álvaro tiene disnea, espirometría obstructiva y compra salbutamol sin fórmula. Un análisis ordenado permite confirmar EPOC, clasificar el grupo, proponer tratamiento y educar. Sin método, el caso se resuelve con intuición y se pierden oportunidades."},"objetivos":["Aplicar el análisis farmacoterapéutico inicial.","Confirmar el diagnóstico y clasificar el grupo.","Proponer el tratamiento inicial según GOLD 2026.","Diseñar educación y seguimiento."],"conceptos":[{"icono":"ClipboardList","termino":"Análisis","definicion":"Proceso ordenado de evaluación."},{"icono":"Gauge","termino":"GOLD 2","definicion":"FEV1 entre 50 y 79 %."},{"icono":"Layers","termino":"Grupo B","definicion":"Síntomas sin exacerbaciones."},{"icono":"Pill","termino":"LABA+LAMA","definicion":"Tratamiento inicial recomendado."}],"secciones":[{"titulo":"Evaluación","parrafos":["Se confirma la espirometría posbroncodilatador con FEV1/FVC menor de 0,70 y se clasifica la obstrucción por el FEV1. Se cuentan las exacerbaciones moderadas o graves del último año y se valoran los síntomas con mMRC o CAT. También se revisan comorbilidades, medicamentos actuales y capacidad para usar dispositivos.","En el caso, don Álvaro tiene EPOC GOLD 2, grupo B por síntomas sin exacerbaciones. No hay rasgos de asma. El salbutamol que compra sin fórmula es un rescate, no un tratamiento de mantenimiento."]},{"titulo":"Propuesta","parrafos":["GOLD 2026 recomienda iniciar LABA+LAMA, preferiblemente en un solo inhalador, en el grupo B. No hay indicación de ICS porque no hay exacerbaciones ni eosinófilos elevados. El salbutamol queda como rescate.","La propuesta se comunica al médico con la evidencia del caso y se documenta. El QF verifica la cobertura del dispositivo, enseña la técnica y refuerza la cesación tabáquica y la vacunación."]},{"titulo":"Seguimiento","parrafos":["Se agenda control en cuatro a ocho semanas para evaluar síntomas, técnica, adherencia y efectos adversos. Se revisa el uso de rescate y se pregunta por exacerbaciones. Si el paciente sigue sintomático con buena adherencia y técnica, se valora escalar el tratamiento.","La educación incluye signos de alarma, plan de acción y cuándo consultar. El caso muestra que el análisis ordenado convierte una consulta de dispensación en una intervención completa."]}],"errores":[{"error":"Iniciar ICS sin indicación.","correccion":"Riesgo de neumonía sin beneficio claro."},{"error":"No evaluar la técnica.","correccion":"El dispositivo debe ser usable."},{"error":"No contar exacerbaciones.","correccion":"Definen el grupo y el tratamiento."}],"comprueba":[{"pregunta":"¿Qué grupo tiene don Álvaro?","respuesta":"Grupo B."},{"pregunta":"¿Qué tratamiento inicial corresponde?","respuesta":"LABA+LAMA."},{"pregunta":"¿Cuándo se indicaría ICS?","respuesta":"Con exacerbaciones y eosinófilos elevados."}],"resumen":["El análisis ordenado evita decisiones intuitivas.","La espirometría confirma y clasifica.","El grupo ABE guía el tratamiento.","La educación completa la intervención."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Ficha de análisis con espirometría, síntomas y propuesta.","alt":"Caso de EPOC en adulto exfumador"}],"keywords":["caso epoc","análisis farmacoterapéutico epoc","gold grupo b","laba lama"],"mapa":{"centro":"Caso EPOC","ramas":[{"titulo":"Diagnóstico","icono":"LineChart","nodos":["FEV1/FVC","GOLD 2","Exposición"]},{"titulo":"Síntomas","icono":"ClipboardList","nodos":["mMRC 2","CAT 18","Sin exacerbaciones"]},{"titulo":"Tratamiento","icono":"Pill","nodos":["LABA+LAMA","Rescate","Sin ICS"]},{"titulo":"Educación","icono":"Users","nodos":["Técnica","Vacunas","Cesación"]}]},"proceso":{"titulo":"Análisis del caso","intro":"","pasos":[{"titulo":"Confirmar","detalle":"Espirometría posbroncodilatador.","icono":"LineChart","evidencia":"Informe."},{"titulo":"Clasificar","detalle":"GOLD y grupo ABE.","icono":"Gauge","evidencia":"Estadio."},{"titulo":"Revisar","detalle":"Medicación y comorbilidades.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Proponer","detalle":"LABA+LAMA y rescate.","icono":"Pill","evidencia":"Nota."},{"titulo":"Educar","detalle":"Técnica, vacunas y cesación.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Don Álvaro","contexto":"Exfumador de 62 años con EPOC GOLD 2, grupo B, sin exacerbaciones y sin rasgos de asma.","pregunta":"¿Cuál es el tratamiento inicial?","opciones":[{"texto":"Solo salbutamol a necesidad.","correcta":false,"retro":"No es mantenimiento."},{"texto":"LABA+LAMA en un inhalador.","correcta":true,"retro":"Recomendación de GOLD 2026 para grupo B."},{"texto":"Triple terapia con ICS.","correcta":false,"retro":"No hay indicación de ICS."}]}}$j$::jsonb;
