  -- 07. Introducción a la unidad: familias de medicamentos y vía inhalada
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"El jarabe que no llega al pulmón","texto":"En un hospital de Villavicencio, el QF encuentra jarabe de salbutamol y teofilina oral para tratar asma. La vía inhalada logra más efecto con menos dosis, pero depende de la técnica. Elegir bien la familia y el dispositivo es parte de la seguridad."},"objetivos":["Clasificar las familias de fármacos respiratorios.","Comparar rescate, mantenimiento y controlador.","Reconocer las ventajas de la vía inhalada.","Identificar medicamentos no recomendados."],"conceptos":[{"icono":"Pill","termino":"Rescatador","definicion":"Alivia rápido la broncoconstricción."},{"icono":"Timer","termino":"Mantenimiento","definicion":"Broncodilatador de acción prolongada."},{"icono":"ShieldCheck","termino":"Controlador","definicion":"Corticoide inhalado que reduce la inflamación."},{"icono":"Wind","termino":"Vía inhalada","definicion":"Más efecto local con menos dosis sistémica."}],"secciones":[{"titulo":"Tres papeles distintos","parrafos":["Los broncodilatadores de acción corta, como el salbutamol y el ipratropio, alivian la broncoconstricción en minutos y se usan como rescate. Los de acción prolongada, como formoterol, salmeterol, vilanterol, tiotropio y otros LAMA, mantienen el bronquio abierto y se usan de forma programada.","Los corticoides inhalados controlan la inflamación y son la base del asma. En la EPOC se reservan para pacientes con exacerbaciones y eosinófilos elevados. Las combinaciones ICS-LABA, LABA+LAMA y triple terapia simplifican el esquema y mejoran la adherencia cuando están indicadas."]},{"titulo":"La vía inhalada","parrafos":["La vía inhalada deposita el fármaco en la vía aérea con dosis mucho menores que la vía oral. Eso reduce los efectos sistémicos, pero exige una técnica correcta. Un inhalador mal usado equivale a un tratamiento que no llega al pulmón.","La elección del dispositivo depende de la capacidad inspiratoria, la destreza manual, la edad y la preferencia del paciente. La cámara espaciadora facilita el uso del inhalador presurizado en niños y en quienes no coordinan."]},{"titulo":"Lo que no se recomienda","parrafos":["GINA 2026 no recomienda el salbutamol oral ni la teofilina oral para el asma por su perfil de eficacia y seguridad. Tampoco se acepta el uso crónico de SABA sin corticoide inhalado. En asma, un LABA nunca debe usarse sin ICS.","El QF revisa la lista de medicamentos y propone alternativas inhaladas cuando encuentra formas orales o esquemas inseguros. La intervención se documenta y se comunica al prescriptor."]}],"errores":[{"error":"Usar formas orales por costumbre.","correccion":"La vía inhalada es preferible."},{"error":"Indicar LABA solo en asma.","correccion":"Siempre con ICS."},{"error":"No enseñar la técnica.","correccion":"Sin técnica no hay efecto."}],"comprueba":[{"pregunta":"¿Qué es un rescate?","respuesta":"Broncodilatador de acción corta."},{"pregunta":"¿Qué es un controlador?","respuesta":"Corticoide inhalado."},{"pregunta":"¿Qué formas no se recomiendan?","respuesta":"Salbutamol oral y teofilina oral."}],"resumen":["Rescate, mantenimiento y control son papeles distintos.","La vía inhalada es la preferida.","El dispositivo debe adaptarse al paciente.","Las formas orales no son la primera opción."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Unidad 2","descripcion":"Familias de inhaladores ordenadas por papel clínico.","alt":"Familias de medicamentos para asma y EPOC"}],"keywords":["familias inhaladores","vía inhalada","saba laba ics lama","teofilina oral"],"mapa":{"centro":"Familias","ramas":[{"titulo":"Rescate","icono":"Zap","nodos":["SABA","SAMA"]},{"titulo":"Mantenimiento","icono":"Timer","nodos":["LABA","LAMA"]},{"titulo":"Control","icono":"ShieldCheck","nodos":["ICS","Antileucotrienos"]},{"titulo":"Combinaciones","icono":"Layers","nodos":["ICS-LABA","LABA+LAMA","Triple"]}]},"proceso":{"titulo":"Cómo elegir la familia","intro":"","pasos":[{"titulo":"Definir","detalle":"Rescate o mantenimiento.","icono":"Target","evidencia":"Objetivo."},{"titulo":"Revisar","detalle":"Enfermedad y comorbilidad.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Elegir","detalle":"Familia y combinación.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Ajustar","detalle":"Dispositivo y técnica.","icono":"Settings","evidencia":"Prueba."},{"titulo":"Verificar","detalle":"Uso correcto en casa.","icono":"Eye","evidencia":"Demostración."}]},"caso":{"titulo":"Jarabe y teofilina","contexto":"Hospital de Villavicencio con uso frecuente de jarabe de salbutamol y teofilina oral para asma.","pregunta":"¿Qué propone el QF?","opciones":[{"texto":"Mantener las formas orales.","correcta":false,"retro":"GINA no las recomienda."},{"texto":"Priorizar inhaladores con ICS y cámaras.","correcta":true,"retro":"Mejor eficacia y seguridad."},{"texto":"Suspender todo tratamiento.","correcta":false,"retro":"El paciente necesita controlador."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: familias de medicamentos y vía inhalada$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: familias de medicamentos y vía inhalada$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 08. SABA y SAMA: salbutamol e ipratropio, uso de rescate y riesgos del sobreuso
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Ocho inhalaciones al día","texto":"Un paciente usa salbutamol casi a diario y cree que está bien porque \"abre el pecho\". El rescate frecuente indica que el asma no está controlada. Contar inhaladores y preguntar por el uso semanal es una intervención sencilla con alto impacto."},"objetivos":["Aplicar la dosis y el uso del salbutamol.","Reconocer los riesgos del sobreuso.","Diferenciar SABA y SAMA.","Educar sobre el rescate y sus límites."],"conceptos":[{"icono":"Zap","termino":"SABA","definicion":"Beta-2 de acción corta; alivia en minutos."},{"icono":"Pill","termino":"Salbutamol","definicion":"100 microgramos por inhalación."},{"icono":"Wind","termino":"Ipratropio","definicion":"Anticolinérgico de acción corta; se añade en crisis."},{"icono":"AlertTriangle","termino":"Sobreuso","definicion":"Más de 2 veces por semana obliga a reevaluar."}],"secciones":[{"titulo":"Salbutamol","parrafos":["El salbutamol estimula los receptores beta-2 del músculo liso bronquial y produce broncodilatación rápida. En adultos y adolescentes se usan 1-2 inhalaciones a necesidad, con un máximo de 8 al día; para prevenir el broncoespasmo por ejercicio, 2 inhalaciones 10-15 minutos antes del desencadenante. En niños de 4 a 11 años, 1 inhalación, hasta 2 si es necesario, sin superar 2 inhalaciones 4 veces al día.","Se agita antes de cada inhalación y, si el inhalador es nuevo o no se usó en 7 días, se liberan 2 disparos al aire. Las reacciones adversas frecuentes son temblor, cefalea, taquicardia y calambres. Con dosis altas puede aparecer hipopotasemia, sobre todo junto con xantinas, corticoides o diuréticos. Los betabloqueantes no selectivos no deben combinarse."]},{"titulo":"Ipratropio y sobreuso","parrafos":["El bromuro de ipratropio bloquea receptores muscarínicos y se añade al salbutamol en exacerbaciones moderadas o con mala respuesta. GOLD también lo considera en la crisis de EPOC. No reemplaza al controlador en el asma.","El sobreuso de SABA es una señal de alarma: usar más de 2 veces por semana, sin contar el ejercicio, obliga a reevaluar. Tres o más inhaladores al año se asocian con exacerbaciones graves y 12 o más con muerte por asma. El SABA regular aumenta la inflamación y reduce su propio efecto."]},{"titulo":"Educación en la dispensación","parrafos":["El QF enseña la diferencia entre el inhalador de rescate y el de mantenimiento, verifica la técnica y pregunta cuántas veces por semana lo usa. Si el paciente no tiene controlador, se remite al médico.","También revisa interacciones, como el propranolol para migraña, y advierte sobre el broncoespasmo paradójico. La educación debe ser práctica y sin culpabilizar: el objetivo es que el paciente reconozca cuándo el rescate ya no es suficiente."]}],"errores":[{"error":"Tratar el asma solo con SABA.","correccion":"Falta el controlador."},{"error":"No agitar el inhalador.","correccion":"La dosis puede ser irregular."},{"error":"No contar el uso.","correccion":"Es un indicador de riesgo."}],"comprueba":[{"pregunta":"¿Dosis máxima diaria en adultos?","respuesta":"8 inhalaciones al día."},{"pregunta":"¿Cuándo reevaluar?","respuesta":"Más de 2 veces por semana."},{"pregunta":"¿Con qué no se combina?","respuesta":"Betabloqueantes no selectivos."}],"resumen":["El SABA alivia pero no controla la inflamación.","El sobreuso es una señal de riesgo.","El ipratropio se añade en crisis.","La educación y el conteo son claves."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Salbutamol Sandoz 100 microgramos/dosis suspensión para inhalación en envase a presión. Revisión mayo 2024.","url":"https://cima.aemps.es/cima/dochtml/ft/70869/FT_70869.html"},{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"SABA y SAMA","descripcion":"Inhalador de rescate y registro de uso semanal.","alt":"Salbutamol e ipratropio en asma y EPOC"}],"keywords":["salbutamol dosis","saba sobreuso","ipratropio crisis","rescate asma"],"mapa":{"centro":"SABA y SAMA","ramas":[{"titulo":"Salbutamol","icono":"Zap","nodos":["1-2 inhalaciones","Máximo 8/día","Agitar"]},{"titulo":"Ipratropio","icono":"Wind","nodos":["Crisis","Añadido","SAMA"]},{"titulo":"Riesgos","icono":"AlertTriangle","nodos":["Temblor","Taquicardia","Hipopotasemia"]},{"titulo":"Educación","icono":"Users","nodos":["Contar uso","Técnica","Consultar"]}]},"proceso":{"titulo":"Revisión del rescate","intro":"","pasos":[{"titulo":"Contar","detalle":"Inhaladores y uso semanal.","icono":"Calculator","evidencia":"Registro."},{"titulo":"Preguntar","detalle":"Síntomas y despertares.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Revisar","detalle":"Técnica y controlador.","icono":"Eye","evidencia":"Observación."},{"titulo":"Intervenir","detalle":"Educación y remisión.","icono":"GraduationCap","evidencia":"Nota."},{"titulo":"Seguir","detalle":"Repetir el conteo.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Propranolol y salbutamol","contexto":"Docente de 40 años en Manizales con asma que toma propranolol para migraña y pide salbutamol.","pregunta":"¿Qué detecta el QF?","opciones":[{"texto":"Ninguna interacción.","correcta":false,"retro":"El betabloqueante no selectivo puede broncoespasmo."},{"texto":"Interacción con betabloqueante no selectivo; remite.","correcta":true,"retro":"Debe revisarse el antimigrañoso."},{"texto":"Debe duplicar el salbutamol.","correcta":false,"retro":"No resuelve el riesgo."}]}}$j$::jsonb;
