  -- 09. LABA y LAMA: formoterol, salmeterol, tiotropio y otros broncodilatadores de mantenimiento
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No todos los LABA son iguales","texto":"Un paciente con asma recibe salmeterol solo y otro usa formoterol con budesonida como rescate. La diferencia entre moléculas cambia el uso clínico. En asma, un LABA nunca va sin corticoide inhalado; en EPOC, LABA+LAMA es la base."},"objetivos":["Diferenciar LABA y LAMA.","Reconocer el inicio de acción de cada LABA.","Aplicar las precauciones del tiotropio.","Elegir mantenimiento según la enfermedad."],"conceptos":[{"icono":"Timer","termino":"LABA","definicion":"Beta-2 de acción prolongada, 12 o 24 horas."},{"icono":"Zap","termino":"Formoterol","definicion":"Inicio rápido; permite rescate con ICS."},{"icono":"Wind","termino":"LAMA","definicion":"Anticolinérgico de acción prolongada."},{"icono":"AlertTriangle","termino":"Precaución","definicion":"Glaucoma, retención urinaria y cardiopatía."}],"secciones":[{"titulo":"LABA","parrafos":["Los LABA estimulan receptores beta-2 durante 12 horas (formoterol, salmeterol) o 24 horas (vilanterol, indacaterol, olodaterol). El formoterol inicia su acción en minutos; por eso, combinado con budesonida o beclometasona, puede usarse como rescate antiinflamatorio y como mantenimiento y rescate. El salmeterol tiene inicio más lento y no se usa como rescate.","En asma, un LABA nunca debe usarse sin corticoide inhalado. En EPOC, LABA y LAMA se combinan como tratamiento inicial en los grupos B y E. La elección depende de la cobertura, el dispositivo y la preferencia del paciente."]},{"titulo":"LAMA y tiotropio","parrafos":["Los LAMA bloquean receptores muscarínicos M3 del músculo liso bronquial. El tiotropio en solución para inhalación se dosifica a 5 microgramos, 2 pulsaciones una vez al día, a la misma hora. Está indicado como mantenimiento en EPOC y como añadido en asma grave con al menos una exacerbación grave en el año previo.","Su ficha técnica pide precaución en glaucoma de ángulo estrecho, hiperplasia prostática u obstrucción del cuello vesical, infarto reciente, arritmias inestables, hospitalización por insuficiencia cardíaca en el último año y depuración de creatinina de 50 mL/min o menos. La boca seca es la reacción más típica y debe evitarse rociar los ojos."]},{"titulo":"Elección en la práctica","parrafos":["En EPOC, GOLD 2026 recomienda LABA+LAMA como tratamiento inicial en los grupos B y E. En asma, el LAMA se añade en el paso 5, o paso 4 en niños, y la triple terapia reduce menos las exacerbaciones graves que los biológicos, aunque es útil en quien no califica para ellos.","El QF verifica que el paciente sepa qué inhalador es de mantenimiento y cuál de rescate, revisa la técnica y detecta duplicidades. También revisa la función renal y los antecedentes oculares y urinarios antes de dispensar tiotropio."]}],"errores":[{"error":"Usar LABA solo en asma.","correccion":"Siempre con ICS."},{"error":"Combinar anticolinérgicos.","correccion":"No se recomienda duplicar."},{"error":"No revisar glaucoma ni próstata.","correccion":"El tiotropio puede agravar."}],"comprueba":[{"pregunta":"¿Qué LABA tiene inicio rápido?","respuesta":"Formoterol."},{"pregunta":"¿Dosis de tiotropio?","respuesta":"5 microgramos una vez al día."},{"pregunta":"¿Qué combinación inicial usa GOLD en grupo B?","respuesta":"LABA+LAMA."}],"resumen":["LABA y LAMA son mantenimiento.","Formoterol permite rescate con ICS.","Tiotropio exige precauciones específicas.","En EPOC, LABA+LAMA es la base."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Spiriva Respimat 2,5 microgramos solución para inhalación. Revisión diciembre 2024.","url":"https://cima.aemps.es/cima/dochtml/ft/69589/FT_69589.html"},{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"LABA y LAMA","descripcion":"Comparación de duración y dispositivos de mantenimiento.","alt":"LABA y LAMA en asma y EPOC"}],"keywords":["laba asma","lama epoc","tiotropio dosis","formoterol rescate","laba lama"],"mapa":{"centro":"Mantenimiento","ramas":[{"titulo":"LABA","icono":"Timer","nodos":["Formoterol","Salmeterol","Vilanterol"]},{"titulo":"LAMA","icono":"Wind","nodos":["Tiotropio","Umeclidinio","Glicopirronio"]},{"titulo":"Asma","icono":"ShieldCheck","nodos":["Con ICS","MART","Paso 5"]},{"titulo":"EPOC","icono":"Layers","nodos":["LABA+LAMA","Grupo B","Grupo E"]}]},"proceso":{"titulo":"Checklist de mantenimiento","intro":"","pasos":[{"titulo":"Enfermedad","detalle":"Asma o EPOC y grupo.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Molécula","detalle":"Inicio y duración.","icono":"Timer","evidencia":"Esquema."},{"titulo":"Combinación","detalle":"Con ICS o LAMA.","icono":"Layers","evidencia":"Fórmula."},{"titulo":"Seguridad","detalle":"Ojos, próstata y riñón.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Técnica","detalle":"Dispositivo y demostración.","icono":"Eye","evidencia":"Prueba."}]},"caso":{"titulo":"EPOC grupo B","contexto":"Paciente con EPOC grupo B que solo usa salbutamol.","pregunta":"¿Qué mantenimiento corresponde?","opciones":[{"texto":"Salmeterol solo.","correcta":false,"retro":"En EPOC se prefiere LABA+LAMA."},{"texto":"LABA+LAMA en un inhalador.","correcta":true,"retro":"Recomendación de GOLD 2026."},{"texto":"Tiotropio con ICS.","correcta":false,"retro":"No hay indicación de ICS."}]}}$j$::jsonb;
