  -- 10. Corticoides inhalados: mecanismo, uso en asma y EPOC y efectos adversos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La cara redondeada por un inhalador","texto":"Un paciente con VIH en tratamiento con ritonavir recibe un corticoide inhalado y desarrolla signos de Cushing. La interacción con inhibidores del CYP3A4 es poco conocida y potencialmente grave. Revisarla en la dispensación previene el evento."},"objetivos":["Explicar el mecanismo de los ICS.","Aplicar su uso en asma y EPOC.","Reconocer efectos adversos locales y sistémicos.","Detectar interacciones del CYP3A4."],"conceptos":[{"icono":"ShieldCheck","termino":"ICS","definicion":"Corticoide inhalado que reduce la inflamación."},{"icono":"Wind","termino":"Asma","definicion":"Todo paciente debe recibir ICS."},{"icono":"AlertTriangle","termino":"Neumonía","definicion":"Riesgo en EPOC tratada con ICS."},{"icono":"Pill","termino":"CYP3A4","definicion":"Inhibidores aumentan la exposición sistémica."}],"secciones":[{"titulo":"Mecanismo y uso","parrafos":["Los corticoides inhalados reducen la inflamación de la vía aérea. En asma son la base del tratamiento: disminuyen síntomas, exacerbaciones y muertes. GINA 2026 indica que todo paciente con asma debe recibir tratamiento con ICS, que se puede reducir tras 2-3 meses de buen control, pero que en adultos y adolescentes no debe suspenderse por completo.","En EPOC su papel es más limitado: se añaden a LABA+LAMA en pacientes con exacerbaciones y eosinófilos elevados, y aumentan el riesgo de neumonía. La indicación debe revisarse periódicamente para retirarlos cuando el perfil de riesgo cambia."]},{"titulo":"Efectos adversos","parrafos":["Las reacciones locales incluyen candidiasis orofaríngea, disfonía, irritación de garganta y tos. Enjuagar la boca después de las dosis de mantenimiento reduce el riesgo. Con dosis altas y uso prolongado pueden aparecer efectos sistémicos: supresión suprarrenal, cataratas, glaucoma, alteraciones visuales y retraso del crecimiento en niños.","Los ICS no se inician durante una exacerbación y no se suspenden bruscamente. En EPOC, la neumonía es el riesgo más relevante y debe considerarse al mantener el tratamiento a largo plazo."]},{"titulo":"Interacción con CYP3A4","parrafos":["Los inhibidores potentes del CYP3A4, como ketoconazol, itraconazol, ritonavir y otros inhibidores de proteasa del VIH, aumentan la exposición sistémica al corticoide y deben evitarse o vigilarse. Esto es especialmente relevante en programas de VIH en Colombia.","El QF pregunta por estos medicamentos, reconoce signos de Cushing y reporta la sospecha al Programa Nacional de Farmacovigilancia. La intervención temprana evita complicaciones y permite ajustar el esquema con el médico."]}],"errores":[{"error":"Usar ICS en EPOC sin criterios.","correccion":"Riesgo de neumonía."},{"error":"No indicar el enjuague.","correccion":"Candidiasis y disfonía."},{"error":"No revisar inhibidores del CYP3A4.","correccion":"Riesgo de Cushing."}],"comprueba":[{"pregunta":"¿Quién debe recibir ICS en asma?","respuesta":"Todo paciente con asma."},{"pregunta":"¿Cuándo se usa ICS en EPOC?","respuesta":"Con exacerbaciones y eosinófilos elevados."},{"pregunta":"¿Qué fármacos aumentan su exposición?","respuesta":"Inhibidores potentes del CYP3A4."}],"resumen":["El ICS es la base del asma.","En EPOC se reserva para perfiles específicos.","Enjuagar reduce efectos locales.","Los inhibidores del CYP3A4 exigen vigilancia."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Symbicort Turbuhaler 160 microgramos/4,5 microgramos/inhalación. Revisión febrero 2021.","url":"https://cima.aemps.es/cima/dochtml/ft/63958/FT_63958.html"},{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"ICS","descripcion":"Corticoide inhalado con recomendaciones de enjuague y control.","alt":"Corticoides inhalados en asma y EPOC"}],"keywords":["corticoides inhalados","ics asma","ics epoc","cyp3a4 budesonida","candidiasis oral"],"mapa":{"centro":"Corticoides inhalados","ramas":[{"titulo":"Asma","icono":"ShieldCheck","nodos":["Base","Todos los pasos","No suspender"]},{"titulo":"EPOC","icono":"Filter","nodos":["Exacerbaciones","Eosinófilos","Neumonía"]},{"titulo":"Adversos","icono":"AlertTriangle","nodos":["Candidiasis","Disfonía","Cushing"]},{"titulo":"Interacción","icono":"Pill","nodos":["Ritonavir","Ketoconazol","Itraconazol"]}]},"proceso":{"titulo":"Revisión del ICS","intro":"","pasos":[{"titulo":"Indicación","detalle":"Asma o EPOC con criterios.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Dosis","detalle":"Baja, media o alta.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Técnica","detalle":"Enjuague y dispositivo.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Interacción","detalle":"CYP3A4 y otros.","icono":"AlertTriangle","evidencia":"Lista."},{"titulo":"Seguir","detalle":"Adversos y control.","icono":"CalendarClock","evidencia":"Registro."}]},"caso":{"titulo":"VIH y Cushing","contexto":"Hombre de 38 años en Barranquilla con VIH en tratamiento potenciado con ritonavir, que recibe ICS y presenta cara redondeada y aumento de peso.","pregunta":"¿Qué sospecha el QF?","opciones":[{"texto":"Es normal por el asma.","correcta":false,"retro":"Los signos sugieren efecto sistémico."},{"texto":"Cushing por interacción con ritonavir; comunica y reporta.","correcta":true,"retro":"Los inhibidores del CYP3A4 aumentan la exposición."},{"texto":"Debe duplicar la dosis.","correcta":false,"retro":"Empeoraría el efecto sistémico."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Corticoides inhalados: mecanismo, uso en asma y EPOC y efectos adversos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Corticoides inhalados: mecanismo, uso en asma y EPOC y efectos adversos$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (137_experiencias_farmacoterapia_asma_epoc_1.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacoterapia del Asma y la EPOC$t$, v_n;
END $exp$;
